// Standalone fallback: resolve the pricing-relevant client_config from Notion by client_id.
const trigger = $('Execute Workflow Trigger').first().json;
const wantId = trigger.client_id;
const rows = $input.all();
function prop(props, name){ const p = props && props[name]; if(!p) return null; if(typeof p==='string') return p; return p.value ?? p.name ?? p.email ?? p.checkbox ?? p.text ?? p ?? null; }
let match=null;
for(const r of rows){ const props=r.json.properties||r.json; if(prop(props,'client_id')===wantId){ match=props; break; } }
if(!match) throw new Error(`No client registry row found for client_id='${wantId}'`);
const client_config = {
  client_id: wantId,
  client_name: prop(match,'Client Name'),
  pricing_sheet_id: prop(match,'pricing_sheet_id'),
  commercial_contact_email: prop(match,'commercial_contact_email'),
  notification_chat_id: prop(match,'notification_chat_id')
};
return [{ json: { client_id: wantId, client_config, data: trigger.data, status: 'ok', errors: [] } }];

// Single merge point for both branches (config passed in vs looked up standalone).
// Emits a uniform { client_id, client_config, data } that downstream nodes reference by name.
const j = $json;
const client_config = j.client_config || {};
if (!client_config.pricing_sheet_id && !client_config.rate_card) {
  throw new Error(`No pricing source for client '${j.client_id}': set 'pricing_sheet_id' in the Notion registry (the client's pricing Google Sheet) or pass client_config.rate_card. See docs/PRICING-SHEET-TEMPLATE.md.`);
}
return [{ json: { client_id: j.client_id, client_config, data: j.data || {} } }];

// Assemble the rate_card object from the client's pricing sheet rows.
// Expected sheet columns (first tab): type | key | value  (see docs/PRICING-SHEET-TEMPLATE.md).
//   type='rate'  -> key is a labour category, value is its hourly rate.
//   type='param' -> key is one of margin_pct, risk_pct, discount_pct, payment_terms, currency.
// An inline client_config.rate_card (if provided) overrides the sheet entirely.
const env = $('Resolve Config').first().json;
const cfg = env.client_config || {};

let rate_card;
if (cfg.rate_card) {
  rate_card = cfg.rate_card;
} else {
  const rows = $('Read Pricing Sheet').all().map(i => i.json);
  const rate_by_category = {};
  let margin_pct = 0, risk_pct = 0, discount_pct = 0, payment_terms = '', currency = null;
  for (const r of rows) {
    const type = String(r.type ?? '').trim().toLowerCase();
    const key = String(r.key ?? '').trim();
    const val = r.value;
    if (!key) continue;
    if (type === 'rate') { rate_by_category[key] = Number(val); }
    else if (type === 'param') {
      if (key === 'margin_pct') margin_pct = Number(val);
      else if (key === 'risk_pct') risk_pct = Number(val);
      else if (key === 'discount_pct') discount_pct = Number(val);
      else if (key === 'payment_terms') payment_terms = String(val);
      else if (key === 'currency') currency = String(val);
    }
  }
  if (Object.keys(rate_by_category).length === 0) {
    throw new Error(`Pricing sheet for '${env.client_id}' produced no rate rows. Check the tab has columns type|key|value and at least one type='rate' row. See docs/PRICING-SHEET-TEMPLATE.md.`);
  }
  rate_card = { rate_by_category, margin_pct, risk_pct, discount_pct, payment_terms, currency };
}
return [{ json: { client_id: env.client_id, client_config: cfg, data: env.data, rate_card } }];
